+import { test, expect } from "@playwright/test";
+
+const ADMIN = { email: "admin@swa.co.in", password: "admin123!" };
+
+async function loginAsAdmin(page: import("@playwright/test").Page) {
+  await page.goto("http://localhost:3000/login");
+  await page.getByLabel("Email").fill(ADMIN.email);
+  await page.getByLabel("Password").fill(ADMIN.password);
+  await page.getByRole("button", { name: /sign in/i }).click();
+  await expect(page).toHaveURL(/\/dashboard/);
+}
+
+async function fillSelect(page: import("@playwright/test").Page, label: string, option: string) {
+  const group = page.locator("label").filter({ hasText: new RegExp(`^${label}\\s*\\*?$`) }).locator("..");
+  const trigger = group.getByRole("combobox");
+  await trigger.click();
+  await page.getByRole("option", { name: option }).click();
+}
+
+// ── Inquiries ──────────────────────────────────────────────────────────
+
+test("admin creates inquiry via form and sees it in list", async ({ page }) => {
+  await loginAsAdmin(page);
+  await page.goto("http://localhost:3000/inquiries/new");
+
+  await page.getByLabel("Inquiry Date *").fill("2026-06-15");
+  await fillSelect(page, "Inquiry Type", "Design");
+  await page.getByLabel("Client Name *").fill("Tata Chemicals Ltd");
+  await page.getByLabel("Inquiry Source").fill("Referral");
+  await page.getByLabel("Requirement Summary").fill("Test seed — boiler insulation scope");
+  await page.getByLabel("Estimated Value (₹)").fill("1500000");
+  await fillSelect(page, "Priority", "High");
+  await fillSelect(page, "Status", "Open");
+
+  await page.getByRole("button", { name: "Save" }).click();
+
+  // Should navigate to the inquiry list or detail — assert row visible
+  await expect(page.getByText("Tata Chemicals Ltd").first()).toBeVisible({ timeout: 10000 });
+});
+
+// ── Tokens ─────────────────────────────────────────────────────────────
+
+test("admin creates token via form and sees it in list", async ({ page }) => {
+  await loginAsAdmin(page);
+  await page.goto("http://localhost:3000/tokens/new");
+
+  await page.getByLabel("Token Date *").fill("2026-06-20");
+  await fillSelect(page, "Agreement", "Boiler Insulation Design & Supply");
+  await fillSelect(page, "Type", "Query");
+  await fillSelect(page, "Status", "In Progress");
+  await page.getByLabel("Description").fill("Seed test — material query for insulation spec");
+  await page.getByLabel("Tokens Used").fill("0.5");
+  await page.getByLabel("Client Employee Name").fill("Amit Kumar");
+
+  await page.getByRole("button", { name: "Save" }).click();
+
+  // Assert the new token appears in the tokens list
+  await expect(page.getByText("SWA-INQ-001").first()).toBeVisible({ timeout: 10000 });
+});
+
+// ── DRN ────────────────────────────────────────────────────────────────
+
+test("admin creates DRN via form and sees it in list", async ({ page }) => {
+  await loginAsAdmin(page);
+  await page.goto("http://localhost:3000/drns/new");
+
+  await page.getByLabel("Date *").fill("2026-06-18");
+  await fillSelect(page, "Document Type", "Concept Note");
+  await page.getByLabel("Document Nature *").fill("Submittal");
+  await page.getByLabel("Intended User *").fill("Client");
+  await page.getByLabel("Description *").fill("Seed test — concept note for boiler insulation");
+  await fillSelect(page, "Revision", "R0");
+  await fillSelect(page, "Status", "Draft");
+
+  await page.getByRole("button", { name: "Save" }).click();
+
+  // Assert the new DRN appears in the list
+  await expect(page.getByText("Seed test — concept note").first()).toBeVisible({ timeout: 10000 });
+});
+
+// ── Time Logs ──────────────────────────────────────────────────────────
+
+test("admin creates time log via form and sees it in list", async ({ page }) => {
+  await loginAsAdmin(page);
+  await page.goto("http://localhost:3000/time-logs/new");
+
+  await page.getByLabel("Log Date *").fill("2026-06-22");
+  await fillSelect(page, "Employee", "Srujan Patel");
